const broker = ($input.all()[0]?.json?.body?.broker || '').toLowerCase();
const row = $input.first().json.row || {};
function get(...keys){ for(const k of keys){ if(row[k]!==undefined&&row[k]!==null&&String(row[k])!=='') return row[k]; } return ''; }
function num(v){ const n=parseFloat(String(v).replace(/[^\d.-]/g,'')); return isNaN(n)?0:n; }
function parseDate(v){ const d=new Date(v); return isNaN(d.getTime())?'':d.toISOString(); }
let type='',symbol='',quantity=0,unitPrice=0,fee=0,currency='',date='',dataSource='YAHOO';
if(broker==='revolut'){
  type=(get('Type','type')+'').toUpperCase();
  symbol=get('Ticker','ticker','Symbol','symbol','Product','product');
  quantity=num(get('Shares','Quantity','quantity'));
  unitPrice=num(get('Price','Split Price','unitPrice'));
  currency=(get('Currency','currency')||'USD').toUpperCase();
  date=parseDate(get('Date','Time','time'));
  dataSource=get('Ticker','ticker')?'YAHOO':(type==='CRYPTO'||type==='Crypto'?'COINGECKO':'MANUAL');
} else if(broker==='xtb'){
  symbol=get('Symbol','symbol','Instrument','instrument','Name');
  const op=(get('Operation','Type','type','Direction')+'').toUpperCase();
  const instr=(get('Instrument','instrument','Name')+'').toLowerCase();
  const isCfd=instr.includes('cfd')||String(get('CFD','Is CFD'))==='true'||op.includes('CFD');
  if(op.includes('BUY')||op.includes('OPEN LONG')){type=isCfd?'SELL':'BUY';}
  else if(op.includes('SELL')||op.includes('OPEN SHORT')){type=isCfd?'BUY':'SELL';}
  else if(op.includes('DIV')){type='DIVIDEND';}
  else{type='BUY';}
  quantity=num(get('Quantity','Amount','Volume','Size'));
  unitPrice=num(get('Price','Unit Price','Open Price'));
  fee=num(get('Commission','Fees','Fee'));
  currency=(get('Currency','currency')||'USD').toUpperCase();
  date=parseDate(get('Date','Time','Opening Time','Open Time'));
  dataSource=isCfd?'MANUAL':'YAHOO';
}
if(!symbol||!date){ return { json:{ skip:true, reason:'missing symbol/date', row } }; }
return { json:{ activity:{ symbol,dataSource,type,quantity,unitPrice,fee,currency,date }, broker } };
